interface CompanySectionProps {
  form: UseFormReturnType<OnboardingValues>;
}

export function CompanySection({ form }: CompanySectionProps) {
  return (
    <Stack>
      <TextInput
        label="Company name"
        placeholder="Mantine"
        withAsterisk
