import { Select, Stack, Switch } from '@mantine/core';
import { UseFormReturnType } from '@mantine/form';
import { OnboardingValues } from './types';

interface PreferencesSectionProps {
  form: UseFormReturnType<OnboardingValues>;
}

export function PreferencesSection({ form }: PreferencesSectionProps) {
  return (
    <Stack>
      <Select
        label="Language"
        placeholder="Pick language"
        withAsterisk
        data={['English', 'German', 'Spanish', 'French']}
        {...form.getInputProps('preferences.language')}
      />
      <Switch
        label="Subscribe to newsletter"
        {...form.getInputProps('preferences.newsletter', { type: 'checkbox' })}
      />
    </Stack>
  );
}

import { CheckCircleIcon } from '@phosphor-icons/react';
import { Group, Text } from '@mantine/core';

interface SectionControlProps {
  label: string;
  valid: boolean;
}

export function SectionControl({ label, valid }: SectionControlProps) {
  return (
    <Group gap="xs">
      <Text fw={500}>{label}</Text>
      {valid && <CheckCircleIcon size={20} weight="fill" color="var(--mantine-color-green-6)" />}
    </Group>
  );
}

export interface OnboardingValues {
  personal: {
    firstName: string;
    lastName: string;
    email: string;
  };
  company: {
    name: string;
    website: string;
  };
  preferences: {
    language: string | null;
    newsletter: boolean;
  };
}
